def r_tagAppendAttributes(tag, *args, cssSelector=None, **kwargs):
    """
    Append attributes to HTML tags (htmltools::tagAppendAttributes).
    """
    from html.parser import HTMLParser
    import re

    if isinstance(tag, str):
        # Parse HTML string
        html_str = tag

        # Filter attributes: remove None values and empty strings
        # But keep None/NaN if it's meant to be a boolean attribute marker
        filtered = {}
        for k, v in kwargs.items():
            if v is None or (isinstance(v, float) and v != v):
                # NA/None becomes a boolean attribute
                filtered[k] = None
            elif not (isinstance(v, str) and len(v) == 0):
                filtered[k] = v

        if cssSelector is not None:
            # Find and modify the specific selector
            # Simple approach: find the opening tag matching cssSelector
            pattern = r'<' + cssSelector + r'(\s[^>]*)?>|<' + cssSelector + r'>'

            def replace_tag(match):
                tag_str = match.group(0)
                # Extract existing attributes if any
                if ' ' in tag_str:
                    tag_name_part, attrs_part = tag_str.split(' ', 1)
                    attrs_part = attrs_part.rstrip('>')
                    # Add new attributes
                    new_attrs = ' ' + attrs_part
                    for k, v in filtered.items():
                        if v is None:
                            new_attrs += f' {k}'
                        else:
                            new_attrs += f' {k}="{v}"'
                    return tag_name_part + new_attrs + '>'
                else:
                    # No existing attributes
                    new_attrs = ''
                    for k, v in filtered.items():
                        if v is None:
                            new_attrs += f' {k}'
                        else:
                            new_attrs += f' {k}="{v}"'
                    return tag_str.rstrip('>') + new_attrs + '>'

            html_str = re.sub(pattern, replace_tag, html_str, count=1)
        else:
            # Modify the first tag (root tag)
            # Find the first opening tag
            match = re.match(r'<(\w+)(\s[^>]*)?>|<(\w+)>', html_str)
            if match:
                tag_name = match.group(1) or match.group(3)
                full_tag = match.group(0)

                if ' ' in full_tag and full_tag.rstrip('>') != f'<{tag_name}':
                    # Has existing attributes
                    tag_name_part, attrs_part = full_tag.split(' ', 1)
                    attrs_part = attrs_part.rstrip('>')
                    new_attrs = ' ' + attrs_part
                    for k, v in filtered.items():
                        if v is None:
                            new_attrs += f' {k}'
                        else:
                            new_attrs += f' {k}="{v}"'
                    new_tag = tag_name_part + new_attrs + '>'
                else:
                    # No existing attributes
                    new_attrs = ''
                    for k, v in filtered.items():
                        if v is None:
                            new_attrs += f' {k}'
                        else:
                            new_attrs += f' {k}="{v}"'
                    new_tag = f'<{tag_name}{new_attrs}>'

                html_str = html_str.replace(full_tag, new_tag, 1)

        return html_str

    # Fallback for non-string tag objects
    return tag
